exercise.prelude:
// Provided: a tiny stand-in for fetch that resolves after 30ms.
function fakeFetch(url) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const id = Number(url.split('/').pop());
      if (id === 1) {
        resolve({ ok: true, json: async () => ({ id: 1, name: 'Ada Lovelace' }) });
      } else if (id === 2) {
        resolve({ ok: true, json: async () => ({ id: 2, name: 'Grace Hopper' }) });
      } else {
        reject(new Error('User not found'));
      }
    }, 30);
  });
}

