class Cart {
  #items = [];

  add(name, price) {
    this.#items.push({ name, price });
  }

  remove(name) {
    this.#items = this.#items.filter((item) => item.name !== name);
  }

  get total() {
    return this.#items.reduce((sum, item) => sum + item.price, 0);
  }

  get count() {
    return this.#items.length;
  }
}
